      "classification": "ACERVO DE BABEL",
      "approved": false,
      "paragraphs": [
        "Idade: 16 anos\nCargo: Jornalista, apresentadora e correspondente\nAfiliação: Imprensa de Babel",
        "As transmissões que levam sua voz de um andar a outro passam quase sempre pela infraestrutura da Vox Meridian Comunicações, embora Agnes não trabalhe para a empresa e faça questão de lembrar essa diferença.",
        "Agnes Ironbeard é uma das jornalistas mais reconhecidas de Babel. Sua voz atravessa terminais públicos, estações ferroviárias e transmissões domésticas quase todos os dias, cobrindo desde decisões da Coroa até acidentes industriais, julgamentos, greves e interrupções nas linhas de transporte.",
        "Começou a carreira como repórter de rua, passando boa parte dos primeiros anos entre as Fornalhas e os Cortiços. A fama veio aos poucos, principalmente pela insistência em entrevistar as pessoas coisas que a levava constantemente a situação problemáticas, ainda assim focava seus esforços em falar com: operários, técnicos, familiares de mortos, guardas e moradores evacuados.",
        "Agnes é conhecida também pelo jeito direto de conduzir entrevistas. Não grita e raramente perde a educação, mas possui o hábito desagradável de falar mais que seus convidados, normalmente fazendo com que suas entrevistas durem o dobro do tempo.",
        "Ser uma goblin contribuiu para tornar sua presença ainda mais reconhecível. Agnes é baixa mesmo para os padrões humanos, tem grandes orelhas pontudas, pele verde-oliva e um sorriso cheio de dentes pequenos e afiados que aparece com frequência enquanto ela fala.",
        "Goblins de Babel amadurecem e começam a trabalhar mais cedo do que humanos. Aos dezesseis anos, Agnes ainda é considerada jovem pelos goblins mais velhos, embora já tenha idade para a carreira que construiu. Quem estranha costuma estar comparando sua trajetória com a de uma adolescente humana.",
        "Sua reputação não vem de neutralidade absoluta. Agnes possui opiniões e não faz muito esforço para esconder algumas delas, principalmente quando empresas tentam minimizar mortes em acidentes ou quando departamentos da Coroa passam responsabilidades de uma mesa para outra. Isso já lhe rendeu processos, ameaças e algumas suspensões temporárias de transmissão.",
        "Entre a população, tornou-se comum ouvir “A Ironbeard falou” quando uma notícia começa a circular de verdade. Normalmente é seguido por alguém perguntando o que exatamente ela falou, porque citar Agnes corretamente parece ser uma habilidade menos popular do que citar Agnes.",
        "“Meu antepassado pode ter morrido sem sua voz ser ouvida, MAS A MINHA VAI SER OUVIDA EM TODO LUGAR!...Agora me diga, os atrasos na linha 7, vão continuar até quanto?!\""
      ],
