      "paragraphs": [
        "Idade: 69 anos\nCargo: Hierofante de Babel\nAfiliação: Igreja Solar",
        "Ambrósio Tavares ocupa o posto mais alto da Igreja Solar em Babel. É ele quem conduz as grandes cerimônias religiosas da cidade, representa o clero diante da Coroa e costuma aparecer nas transmissões quando a presença do clero é pedida.",
        "Antes de chegar ao alto clero, passou muitos anos servindo nos templos das Fornalhas e dos Cortiços. Ainda mantém alguns hábitos dessa época.",
        "Essa proximidade ajudou a torná-lo popular muito além dos fiéis mais devotos. Durante apagões, acidentes industriais e evacuações, Ambrósio costuma cobrar publicamente que templos permaneçam abertos como abrigo e que lanternas, comida e água sejam distribuídas.",
        "As câmeras aparecem com frequência nessas visitas, claro.",
        "Na Coroa, é uma figura mais difícil de classificar. Mantém uma relação pública respeitosa com Octavia Vanyar, participa das principais cerimônias de Estado e raramente entra em conflito aberto com o governo. Isso não o impede de criticar decisões quando acredita que atingem diretamente os templos. Ambrósio sabe escolher as palavras, embora nem sempre escolha palavras agradáveis.",
        "“Que faça-se a LUZ!\""
      ],
