      "classification": "ACERVO DE BABEL",
      "approved": false,
      "paragraphs": [
        "Idade: 44 anos  \nCargo: Cantora, compositora e atriz  \nAfiliação: Independente",
        "Anna Rossa é uma das artistas mais famosas de Babel. Sua voz já passou por tavernas nos Cortiços, salões lotados nos Jardins e cerimônias privadas na Coroa, embora ela própria goste de lembrar que começou cantando em lugares mais simples.",
        "Nascida nos Cortiços, Anna passou anos se apresentando em bares, casas de \"espetáculo\" e pequenos teatros antes de chegar aos grandes palcos. O sucesso não apagou essa origem, embora tenha mudado bastante o quanto ela recebe pelos shows. Hoje seus espetáculos envolvem músicos, atores, cenários mecânicos e figurinos extremamente luxuosos.",
        "Fora dos palcos, Anna tem exatamente a reputação que se espera de uma diva: Sempre chega atrasada, muda constantemente de ideia e de figurino, isso sem falar quando ela não resolve mudar também o roteiro.",
        "Sua popularidade atravessa boa parte das divisões de Babel. Operários das Fornalhas cantam músicas antigas durante o turno, comerciantes colocam seu nome em bebidas e famílias dos Jardins disputam lugares para suas apresentações. A elite gosta de tratá-la como prova de que qualquer pessoa pode subir em Babel.",
        "A imprensa acompanha seus romances, brigas, vestidos e opiniões com uma dedicação que provavelmente seria mais útil aplicada a outros assuntos. Agnes Ironbeard já a entrevistou diversas vezes; as duas se respeitam o bastante para continuar discordando em público sempre que surge uma oportunidade.",
        "Anna sabe muito bem que parte de sua carreira depende do espetáculo continuar mesmo depois que a música termina. Por isso, quase nunca aparece em público sem estar preparada para ser lembrada.",
        "“Falem bem, falem mal, mas falem de mim\""
      ],
