      "paragraphs": [
        "Idade: 64 anos\nCargo: Industrialista e Presidente do Grupo Meier\nAfiliação: Grupo Meier",
        "Augusto Meier é um dos maiores nomes da indústria de Babel. Suas companhias possuem contratos ligados à produção pesada, peças ferroviárias, equipamentos de mineração e componentes usados na manutenção das grandes estruturas da cidade. O nome Meier aparece tanto em documentos da Coroa quanto gravado em máquinas nas Fornalhas que provavelmente continuarão funcionando depois da morte de seu atual proprietário.",
        "Nascido nas As Fornalhas, Augusto começou trabalhando dentro das próprias fábricas da família, quando os Meier ainda estavam longe de ser uma das grandes fortunas de Babel. Décadas depois, já morando na Coroa, continua visitando velhos colegas e amigos que ainda vivem nas Fornalhas.",
        "Sua ascensão virou uma das histórias favoritas de quem gosta de apresentar Babel como uma cidade onde qualquer pessoa pode subir. Augusto raramente corrige essa versão, embora também não esconda que herdou uma empresa funcionando, bons contatos e um sobrenome conhecido nas Fornalhas. Seu mérito se formos honestos é o de ter transformado tudo aquilo em algo maior.",
        "Entre trabalhadores, sua reputação é complicada. Os salários das empresas Meier costumam ser melhores que a média industrial, e acidentes graves são mais rapidamente investigados do que em muitas das suas concorrentes. Greves, indenizações e redução de jornada já colocaram os dois lados na mesma mesa diversas vezes, quase sempre por muitas horas e com pouca cordialidade.",
        "“Estou ocupado, fale com minha secretaria!\""
      ],
