      "id": "babel-5ba6b73ecafd8c01",
      "title": "Briga de Foice",
      "category": "pessoas",
      "folder": "pessoas/babel",
      "group": "pessoas",
      "theme": "babel",
      "classification": "ACERVO DE BABEL",
      "approved": false,
      "paragraphs": [
        "Idade: 39 anos  \nCargo: Contrabandista, atravessador e criminoso reincidente  \nAfiliação: Independente",
        "Briga de Foice é um dos contrabandistas mais conhecidos de Babel, embora chamar sua carreira de bem-sucedida seja generoso. Seu nome aparece com frequência em boletins policiais, jornais baratos e conversas na estação, geralmente acompanhado de alguma variação de “preso novamente”.",
        "Sua fama não veio de grandes roubos ou de uma reputação sanguinária. Briga de Foice ficou conhecido por transportar praticamente qualquer coisa que consiga esconder num vagão, numa caixa ou debaixo do próprio casaco ou as vezes até em seu corpo: remédios sem licença, peças roubadas, cristais, documentos falsificados, bebidas vindas da Coroa.",
        "O problema é que ele vive sendo pego.",
        "Já passou tantas vezes por delegacias dos Cortiços e do Fosso que existem guardas que o cumprimentam pelo apelido antes mesmo de perguntar o que está carregando. Em toda prisão, a história é parecida. Briga de Foice garante que aprendeu a lição, promete procurar trabalho honesto, fala sobre abrir uma pequena loja e jura pela última vez que abandonou o contrabando.",
        "Algumas semanas depois, alguém o encontra tentando roubar alguém, passar com documentos falsos em uma guarita ou só vendendo drogas.",
        "Apesar da fama quase cômica, ele é bom no que faz quando consegue chegar ao destino. Conhece rotas que são consideradas esquecidas pelos arquitetos, horários de fiscalização e muito mais. Também possui a estranha habilidade de conhecer alguém em praticamente qualquer estação dos andares baixos. Metade desses conhecidos parece dever dinheiro a ele ou ele que deve...tanto faz!",
        "Briga de Foice fala muito, especialmente quando seria melhor ficar quieto. É simpático quando precisa, descarado quando não precisa e possui uma confiança impressionante na própria capacidade de convencer guardas que já o prenderam anteriormente. Não costuma procurar briga e prefere correr quando armas aparecem. Segundo ele, criminoso morto não consegue pagar a fiança.",
        "Ninguém sabe exatamente de onde veio o apelido Briga de Foice. Quando perguntam, ele conta uma história diferente. Numa versão havia dois fazendeiros, três foices e uma mulher casada. Em outra, eram sete homens numa estação das Fundações.",
        "Sempre que alguém ve ele, não podem deixar de rir da cara feia do homem falando ;",
        "“Nada mais feio que briga de foice!”"
      ],
