      "id": "babel-60ef1b74e5cfa6e6",
      "title": "Dalva Ferraz — Mãe-Rebite",
      "category": "pessoas",
      "folder": "pessoas/babel",
      "group": "pessoas",
      "theme": "babel",
      "classification": "ACERVO DE BABEL",
      "approved": false,
      "paragraphs": [
        "Vínculo: Sexto Andar",
        "Dalva já era chamada de Mãe-Rebite antes de ter cabelos brancos. Na época, coordenava reparos de emergência e puxava aprendizes para longe das máquinas abertas enquanto os chamava de “meu filho”. O apelido ficou entre os trabalhadores e acompanhou a anã quando passou a ajudar sindicatos das Fornalhas, Fundações e Fosso a negociar em conjunto. Ela não dirige todas essas organizações; costuma ser procurada justamente quando as diretorias concordam sobre o problema, mas começam a disputar quem vai falar por elas.",
        "Perdeu mobilidade numa perna e usa uma prótese pesada feita em oficina sindical. Isso não a tornou paciente nem a impediu de participar de uma briga, embora prefira resolver a discussão antes que alguém levante uma cadeira. Conhece contratos, famílias de feridos e supervisores que mudaram a maneira de trabalhar depois de receber pressão. Ao avaliar uma proposta, quer saber o que ela vai resolver e quem ficará responsável pelo serviço; não presume que todo trabalhador esteja certo ou que nenhum patrão possa cumprir um acordo.",
        "Dalva gosta de cartas, comida muito apimentada e jovens que sustentam uma discordância com argumentos. O que a irrita é receber tratamento de avó frágil de gente que mal a conhece. O “Mãe” carrega afeto e uma história política entre os trabalhadores, e ela não entende por que isso deveria ser motivo para começarem a falar por ela."
      ],
