      "id": "babel-9069501f494948a5",
      "title": "Durkan Bull",
      "category": "pessoas",
      "folder": "pessoas/babel",
      "group": "pessoas",
      "theme": "babel",
      "classification": "ACERVO DE BABEL",
      "approved": false,
      "paragraphs": [
        "Idade: 47 anos  \nCargo: Advogado e fundador da Bell & Associados  \nAfiliação: Bull & Associados",
        "Durkan Bull é provavelmente o advogado mais reconhecível de Babel. Parte disso vem das causas que venceu. O resto vem do fato de que é difícil atravessar uma estação, pegar um elevador público ou caminhar duas ruas nas Fornalhas sem encontrar o rosto enorme de um Orc de terno apontando diretamente para você.",
        "A Bull & Associados trabalha principalmente com acidentes industriais, indenizações, demissões, contratos, problemas com licenças e disputas contra companhias. É um campo particularmente fértil em uma cidade onde cada distrito pode ter suas próprias regras, atravessar determinadas fronteiras exige documentação e a Coroa decide desde licenças de guilda até rotas de transporte.",
        "Durkan construiu a carreira atendendo trabalhadores das Fornalhas e dos Cortiços. Nunca cultivou a imagem de um defensor dos humilde ou dos pobres. Pelo contrario, ele cobra caro, mas te garante que não importa a causa, o Bull vai te defender.",
        "Os anúncios de Durkan são famosos. Há cartazes com o rosto dele perto de hospitais, fábricas, delegacias e estações. Pequenos terminais repetem propagandas da Bull & Associados entre notícias e horários de trem.",
        "Sua fama também produziu uma relação curiosa com a população. Há quem considere seus anúncios insuportáveis. Há quem guarde um cartão da Bull & Associados na carteira desde o primeiro emprego industrial.",
        "Atualmente seu melhor cliente é Jonas Ravencroft Von Eregor V...é impressionante o número de problemas que o melhor caçador de BABEL pode ter.",
        "“Não assine. Não confesse. Não pague. Chame o Bull.”\n\"Better Call The Bull\""
      ],
