      "paragraphs": [
        "Vínculo: Igreja Solar",
        "Gaspar é grande até para um vesk e se abaixa ao entrar nos quartos dos abrigos para não aumentar o nervosismo de quem está lá. Coordena estoques de emergência e voluntários entre vários andares, carrega caixas quando faltam braços e tenta aliviar a espera com piadas que nem sempre funcionam. Lembra aniversários e consegue organizar uma fila sem falar com as famílias como se estivesse comandando uma tropa.",
        "Sua fé aparece muito nesse trabalho. Gaspar acredita que a proteção oferecida pela Igreja precisa chegar também a quem não pode pagar, e cobra isso da própria instituição. Respeita Ambrósio, mas já discordou dele em público levando números, nomes de capelas e pedidos que continuavam sem resposta. Quer que a Igreja cuide dos bairros com a atenção que dedica aos altares, por isso continua trabalhando dentro dela mesmo quando a discussão se torna desagradável.",
        "Anos de evacuações ensinaram a reconhecer uma multidão prestes a se esmagar, abrir uma porta que precisa ceder e enfrentar alguém armado quando há pessoas sem saída atrás dele. Gaspar evita violência sempre que consegue, embora seja excelente numa briga. Depois que o perigo passa, ainda é preciso recolher cobertores e cuidar de quem ficou no abrigo, e ele costuma voltar a esse serviço antes de discutir quem tinha autoridade para fazer o quê."
      ],
      "assets": [
        {
          "id": "art-45721a7a300241cb",
          "title": "Babel - Gaspar Kest",
          "path": "assets/lore/45721a7a300241cb.png",
          "source": "module"
        }
      ],
